#include <stdio.h>
long long work_prefix(long long year, int month, int day) {
    const int length[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    long long y = year - 1, elapsed = 365 * y + y / 4 - y / 100 + y / 400 + day - 1;
    for (int m = 1; m < month; m++)
        elapsed += length[m] +
                   (m == 2 && year % 4 == 0 && (year % 100 != 0 || year % 400 == 0));
    int tail = elapsed % 7;
    return elapsed / 7 * 5 + (tail < 5 ? tail : 5);
}
int main(void) {
    long long start, end;
    int a, b, c, d;
    scanf("%lld%d%d%lld%d%d", &start, &a, &b, &end, &c, &d);
    printf("%lld\n", work_prefix(end, c, d) - work_prefix(start, a, b));
    return 0;
}

