#include <stdio.h>
long long eg(long long a, long long b, long long *x, long long *y) {
    if (!b) {
        *x = 1;
        *y = 0;
        return a;
    }
    long long u, v, g = eg(b, a % b, &u, &v);
    *x = v;
    *y = u - a / b * v;
    return g;
}
int main(void) {
    long long a, m, b, n, x, y;
    scanf("%lld%lld%lld%lld", &a, &m, &b, &n);
    long long g = eg(m, n, &x, &y);
    if ((b - a) % g)
        puts("-1");
    else {
        long long mod = n / g, k = ((b - a) / g * x % mod + mod) % mod;
        printf("%lld\n", a + m * k);
    }
    return 0;
}

