typedef struct {
    long long x, y;
} Point;
Point read_point(void) {
    Point p;
    scanf("%lld%lld", &p.x, &p.y);
    return p;
}
long long cross(Point a, Point b, Point p) {
    return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
}
int between(long long x, long long a, long long b) {
    return (a <= x && x <= b) || (b <= x && x <= a);
}
int on(Point a, Point b, Point p) {
    return !cross(a, b, p) && between(p.x, a.x, b.x) && between(p.y, a.y, b.y);
}
int main(void) {
    Point a = read_point(), b = read_point(), c = read_point(), p = read_point();
    long long u = cross(a, b, p), v = cross(b, c, p), w = cross(c, a, p);
    puts(!cross(a, b, c)                                          ? "INVALID"
         : on(a, b, p) || on(b, c, p) || on(c, a, p)              ? "EDGE"
         : (u > 0 && v > 0 && w > 0) || (u < 0 && v < 0 && w < 0) ? "IN"
                                                                  : "OUT");
    if (cross(a, b, c) && (on(a, b, p) || on(b, c, p) || on(c, a, p) ||
                           (u > 0 && v > 0 && w > 0) || (u < 0 && v < 0 && w < 0))) {
        long long num = llabs(v), den = llabs(cross(a, b, c)), x = num, y = den;
        while (y) {
            long long remainder = x % y;
            x = y;
            y = remainder;
        }
        printf("%lld/%lld\n", num / x, den / x);
    }
    return 0;
}

#include <stdio.h>
static int frequency[15], best;
static const char *names[] = {"HIGH",     "PAIR", "TWO_PAIR", "THREE",
                              "STRAIGHT", "FULL", "FOUR"};
static void classify(int wild) {
    if (wild) {
        for (int rank = 1; rank <= 13; rank++)
            if (frequency[rank] < 4) {
                frequency[rank]++;
                classify(wild - 1);
                frequency[rank]--;
            }
        return;
    }
    int pairs = 0, maximum = 0, run = 0, straight = 0;
    for (int rank = 1; rank <= 14; rank++) {
        int count = frequency[rank == 14 ? 1 : rank];
        if (rank <= 13) {
            pairs += count == 2;
            if (count > maximum)
                maximum = count;
        }
        run = count ? run + 1 : 0;
        if (run == 5)
            straight = 1;
    }
    int score = maximum == 4            ? 6
                : maximum == 3 && pairs ? 5
                : straight              ? 4
                : maximum == 3          ? 3
                : pairs == 2            ? 2
                : pairs                 ? 1
                                        : 0;
    if (score > best)
        best = score;
}
int main(void) {
    int wild = 0;
    for (int i = 0, rank; i < 5; i++) {
        scanf("%d", &rank);
        if (rank)
            frequency[rank]++;
        else
            wild++;
    }
    classify(wild);
    puts(names[best]);
    return 0;
}

#include <stdio.h>
typedef struct {
    int y, m, d;
} Date;
int days(int y, int m) {
    static const int length[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    return length[m] + (m == 2 && y % 4 == 0 && (y % 100 != 0 || y % 400 == 0));
}
long long serial(Date date) {
    long long y = date.y - 1, result = 365 * y + y / 4 - y / 100 + y / 400 + date.d - 1;
    for (int i = 1; i < date.m; i++)
        result += days(date.y, i);
    return result;
}
Date settlement(Date start, int year) {
    Date result = {year, start.m, start.d};
    if (result.d > days(year, result.m))
        result.d = days(year, result.m);
    int weekday = serial(result) % 7, delay = weekday >= 5 ? 7 - weekday : 0;
    while (delay--) {
        if (++result.d > days(result.y, result.m)) {
            result.d = 1;
            if (++result.m == 13) {
                result.m = 1;
                result.y++;
            }
        }
    }
    return result;
}
int main(void) {
    Date start, cutoff;
    scanf("%d%d%d%d%d%d", &start.y, &start.m, &start.d, &cutoff.y, &cutoff.m,
          &cutoff.d);
    int year = cutoff.y > start.y + 1 ? cutoff.y - 1 : start.y + 1;
    Date next = settlement(start, year);
    while (serial(next) <= serial(cutoff))
        next = settlement(start, ++year);
    printf("%d %d %d %d\n", year - start.y - 1, next.y, next.m, next.d);
    return 0;
}

