    return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
}
int between(long long x, long long a, long long b) {
    return (a <= x && x <= b) || (b <= x && x <= a);
}
int on(Point a, Point b, Point p) {
    return !cross(a, b, p) && between(p.x, a.x, b.x) && between(p.y, a.y, b.y);
}
int cmp(Point a, Point b) {
    if (a.x != b.x)
        return a.x > b.x ? 1 : -1;
    return (a.y > b.y) - (a.y < b.y);
}
int sg(long long x) { return (x > 0) - (x < 0); }
int main(void) {
    Point a = read_point(), b = read_point(), c = read_point(), d = read_point();
    if (cmp(a, b) > 0) {
        Point t = a;
        a = b;
        b = t;
    }
    if (cmp(c, d) > 0) {
        Point t = c;
        c = d;
        d = t;
    }
    long long u = cross(a, b, c), v = cross(a, b, d), w = cross(c, d, a),
              z = cross(c, d, b);
    if (!u && !v && !w && !z) {
        Point l = cmp(a, c) > 0 ? a : c, r = cmp(b, d) < 0 ? b : d;
        int k = cmp(l, r);
        puts(k > 0 ? "EMPTY" : k == 0 ? "POINT" : "SEGMENT");
    } else
        puts(on(a, b, c) || on(a, b, d) || on(c, d, a) || on(c, d, b) ||
                     (sg(u) * sg(v) < 0 && sg(w) * sg(z) < 0)
                 ? "POINT"
                 : "EMPTY");
    return 0;
}

