#include <stdio.h>
long long valuation(long long n, long long p) {
    long long sum = 0;
    while (n) {
        n /= p;
        sum += n;
    }
    return sum;
}
int main(void) {
    long long n, b, ans = 10000000000000LL;
    scanf("%lld%lld", &n, &b);
    for (long long p = 2; p <= b / p; p++) {
        if (b % p)
            continue;
        int e = 0;
        while (b % p == 0) {
            b /= p;
            e++;
        }
        long long v = valuation(n, p) / e;
        if (v < ans)
            ans = v;
    }
    if (b > 1 && valuation(n, b) < ans)
        ans = valuation(n, b);
    printf("%lld\n", ans);
    return 0;
}

