    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d%d%d%d", &a[i].x, &a[i].y, &a[i].X, &a[i].Y);
        xs[2 * i] = a[i].x;
        xs[2 * i + 1] = a[i].X;
    }
    qsort(xs, 2 * n, sizeof(int), integer);
    long long area = 0;
    for (int j = 1; j < 2 * n; j++) {
        if (xs[j] == xs[j - 1])
            continue;
        int cnt = 0;
        for (int i = 0; i < n; i++)
            if (a[i].x <= xs[j - 1] && a[i].X >= xs[j])
                slice[cnt++] = a[i];
        qsort(slice, cnt, sizeof(Rect), by_y);
        int end = -100000001;
        long long height = 0;
        for (int i = 0; i < cnt; i++)
            if (slice[i].Y > end) {
                int start = slice[i].y > end ? slice[i].y : end;
                height += slice[i].Y - start;
                end = slice[i].Y;
            }
        area += height * (xs[j] - xs[j - 1]);
    }
