#include <stdio.h>
typedef struct {
    long long arrival, left, finish;
} Job;
static Job a[2000];
int main(void) {
    int n, done = 0;
    long long now = 0;
    scanf("%d", &n);
    for (int i = 0; i < n; i++)
        scanf("%lld%lld", &a[i].arrival, &a[i].left);
    while (done < n) {
        int best = -1;
        long long next = 1LL << 60;
        for (int i = 0; i < n; i++) {
            if (!a[i].left)
                continue;
            if (a[i].arrival > now) {
                if (a[i].arrival < next)
                    next = a[i].arrival;
            } else if (best < 0 || a[i].left < a[best].left)
                best = i;
        }
        if (best < 0) {
            now = next;
            continue;
        }
        long long dt = a[best].left;
        if (next - now < dt)
            dt = next - now;
        now += dt;
        a[best].left -= dt;
        if (!a[best].left) {
            a[best].finish = now;
            done++;
        }
    }
    for (int i = 0; i < n; i++)
        printf("%lld\n", a[i].finish);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct {
    int a, b, cost;
} Edge;
static Edge edges[200000];
static int parent[100001];
int root(int x) {
    while (x != parent[x]) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}
int cmp(const void *a, const void *b) {
    const Edge *x = a, *y = b;
    return x->cost - y->cost;
}
int main(void) {
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
        parent[i] = i;
    for (int i = 0; i < m; i++)
        scanf("%d%d%d", &edges[i].a, &edges[i].b, &edges[i].cost);
    qsort(edges, m, sizeof(Edge), cmp);
    int parts = n;
    long long total = 0;
    for (int i = 0; i < m; i++) {
        int a = root(edges[i].a), b = root(edges[i].b);
        if (a != b) {
            parent[a] = b;
            parts--;
            total += edges[i].cost;
        }
    }
    printf("%lld\n", parts == 1 ? total : -1LL);
    return 0;
}
